 3D’omics | Micro-scale spatial metagenomics (MSSM) Work in progress Carlotta Pietroni1 Antton Alberdi2 Amalia Bogri3 2025-07-10 Chapter 1 Introduction This webbook contains all the code used for the analyses of in “Micro-scale spatial metagenomics: revealing high-resolution spatial biogeography of gut microbiomes”. 1.1 Prepare the R environment 1.1.1 Environment To reproduce all the analyses locally, clone this repository in your computer using: RStudio &gt; New Project &gt; Version Control &gt; Git And indicating the following git repository: https://github.com/3d-omics/XXX Once the R project has been created, follow the instructions and code chunks shown in this webbook. 1.1.2 Libraries The following R packages are required for the data analysis. # install.packages(&#39;BiocManager&#39;, dependencies = TRUE) # BiocManager::install(c(&quot;phyloseq&quot;, &quot;ggtreeExtra&quot;,&quot;ggtree&quot;,&quot;ANCOMBC&quot;, &quot;ALDEx2&quot;))&#39; # install.packages(&#39;remotes&#39;, dependencies = TRUE) # remotes::install_github(&#39;anttonalberdi/hilldiv2&#39;) # remotes::install_github(&#39;anttonalberdi/distillR&#39;)&#39; # remotes::install_github(&#39;wilkelab/cowplot&#39;) if(!require(&quot;pacman&quot;)) install.packages(&quot;pacman&quot;) pacman::p_load(tidyverse, rairtable, jsonlite, distillR, ape, hilldiv2, ggpubr, broom, reshape2, zCompositions, ANCOMBC, cowplot, ALDEx2, car, DHARMa, sjPlot, ggeffects, microViz, ggh4x, vegan, ggfortify, ggrepel, microbiome, ggforce, patchwork, grid, pheatmap, janitor, spdep, adespatial, adegraphics, # lmPerm ade4, magick, permuco, airtabler2, rmarkdown, purrr) select &lt;- dplyr::select recode &lt;- dplyr::recode 1.1.3 Notes: 1.1.3.1 Installation of modules Most of the modules can be downloaded from CRAN with ‘install.packages(’XXX’, dependencies = TRUE)‘. Four modules are from Bioconductor. Install with: ’install.packages(’BiocManager’, dependencies = TRUE) BiocManager::install(c(“phyloseq”, “ggtreeExtra”,“ggtree”,“ANCOMBC”, “ALDEx2”))’ Three modules are github. Install with: ‘install.packages(’remotes’, dependencies = TRUE) remotes::install_github(‘anttonalberdi/hilldiv2’) remotes::install_github(‘anttonalberdi/distillR’)’ remotes::install_github(‘wilkelab/cowplot’)’ 1.1.3.2 Airtable access: Currently the metadata is loaded from the 3D’omics airtable. In order to access it you need your own API key (from Antton). set_airtable_api_key(‘XXXXX’, install = TRUE) 1.2 Define Plotting Settings 1.2.1 Color Schemes phylum_colors &lt;- c(Actinomycetota = &quot;#346254&quot;, Bacillota = &quot;#4a6ab7&quot;, Bacillota_A = &quot;#8c1c47&quot;, Bacteroidota = &quot;#9c8464&quot;, Pseudomonadota = &quot;#c49d4b&quot;, Verrucomicrobiota = &quot;#462410&quot;) order_colors &lt;- c(Actinomycetales = &quot;#79b1a3&quot;, Coriobacteriales = &quot;#498a77&quot;, CAJFEE01 = &quot;#a0c5e8&quot;, Erysipelotrichales = &quot;#7acef4&quot;, Lactobacillales = &quot;#6390fb&quot;, ML615J_28 = &quot;#70c9de&quot;, Paenibacillales = &quot;#70a8dc&quot;, RF39 = &quot;#5c7fba&quot;, Christensenellales = &quot;#f58262&quot;, Clostridiales = &quot;#cf4a82&quot;, Lachnospirales = &quot;#e15f7d&quot;, Monoglobales = &quot;#e18299&quot;, Oscillospirales = &quot;#ba2760&quot;, Peptostreptococcales = &quot;#e35d51&quot;, TANB77 = &quot;#ef3d26&quot;, UBA1381 = &quot;#be5643&quot;, Bacteroidales = &quot;#e3c7a0&quot;, Enterobacterales = &quot;#ffcc62&quot;, Verrucomicrobiales = &quot;#823f1d&quot;) lawsonibacter_colors &lt;- c(`GPB:bin_000217` = &quot;#79b1a3&quot;, `GPB:bin_000137` = &quot;darkgrey&quot;, `GPB:bin_000118` = &quot;#7acef4&quot;, `GPB:bin_000080` = &quot;#6390fb&quot;, `GPB:bin_000077` = &quot;#5c7fba&quot;, `GPB:bin_000072` = &quot;lightgreen&quot;, `GPB:bin_000015` = &quot;#cf4a82&quot;, `GPB:bin_000047` = &quot;#e35d51&quot;, `GPB:bin_000044` = &quot;black&quot;, `GPB:bin_000034` = &quot;#e3c7a0&quot;, `GPB:bin_000063` = &quot;#ffcc62&quot;, `D300470:bin_000020` = &quot;darkseagreen3&quot;) 1.2.2 Plotting Theme custom_ggplot_theme &lt;- theme( strip.text.y.left = element_text(angle = 0), strip.text.y.right = element_text(angle = 0), axis.text = element_text(size = 10), axis.title = element_text(size = 12, face = &quot;bold&quot;), strip.background = element_rect(fill = &quot;#dde3e9&quot;, color = &quot;white&quot;, size = 0.8), # Custom facet strip background strip.text = element_text(size = 11, face = &quot;bold&quot;, color = &quot;black&quot;), # Custom facet text 8 strip.placement = &quot;outside&quot;, # Place strip outside the panel grid panel.spacing = unit(0.1, &quot;lines&quot;), # Adjust space between panels panel.grid.major = element_line(color = &quot;#dde3e9&quot;), # Customize major grid lines panel.grid.minor = element_blank(), # Remove minor grid lines panel.background = element_rect(fill = &quot;white&quot;), # Change panel background color plot.margin = unit(c(1, 1, 1, 1), &quot;cm&quot;) # Adjust plot margins to ensure content fits ) 1.3 Load Functions 1.3.1 parse_fastp_function parse_fastp &lt;- function(multiqc_json) { fastp_raw &lt;- multiqc_json$report_saved_raw_data$multiqc_fastp fastp_tibble &lt;- tibble::tibble( sample_id = names(fastp_raw), values = fastp_raw ) |&gt; dplyr::mutate( sample_id = sample_id |&gt; stringr::str_remove_all(&quot;fastp \| &quot;) |&gt; stringr::str_remove(&quot;_[12].fq.gz&quot;) |&gt; stringr::str_split(&quot;_&quot;) |&gt; purrr::map(1) |&gt; unlist() ) |&gt; tidyr::unnest_wider(values) |&gt; tidyr::unnest_wider(-sample_id, names_sep = &quot;.&quot;) |&gt; tidyr::unnest_wider( c( summary.before_filtering, summary.after_filtering, polyx_trimming.polyx_trimmed_reads, polyx_trimming.polyx_trimmed_bases ), names_sep = &quot;.&quot; ) fastp_tibble } 1.3.2 calculate_alpha_diversity calculate_alpha_diversity &lt;- function(input_data, metadata_name, dataset_name, tree_name) { input_data_matrix &lt;- input_data %&gt;% column_to_rownames(var = &quot;genome&quot;) colsum &lt;- input_data_matrix %&gt;% summarise(across(where(is.numeric), sum)) %&gt;% pivot_longer(cols = everything(), names_to = &quot;microsample&quot;, values_to = &quot;cov_filtering&quot;) %&gt;% mutate(cov_filtering=ifelse(cov_filtering &gt; 0 , &quot;Retained By Filtering&quot;, &quot;Excluded By Filtering&quot;)) # Define diversity metrics and calculate diversity_metrics &lt;- list( richness = hilldiv(input_data_matrix, q = 0), neutral = hilldiv(input_data_matrix, q = 1), phylogenetic = hilldiv(input_data_matrix, q = 1, tree = tree_name) ) # Process metrics into a single data frame alpha_diversity &lt;- lapply(names(diversity_metrics), function(metric) { diversity_metrics[[metric]] %&gt;% t() %&gt;% as.data.frame() %&gt;% rownames_to_column(var = &quot;microsample&quot;) %&gt;% rename(!!sym(metric) := 2) # rename metric column }) %&gt;% reduce(full_join, by = &quot;microsample&quot;) %&gt;% right_join(metadata_name, by = &quot;microsample&quot;) %&gt;% # Merge with final stats left_join(colsum, by = &quot;microsample&quot;) #output_filename &lt;- paste0(&quot;results/alpha_div_&quot;, dataset_name, &quot;.tsv&quot;) #write_tsv(alpha_diversity, output_filename) return(alpha_diversity) } 1.3.3 Amalia: perform_pca perform_pca &lt;- function(df, zero_method = &quot;GBM&quot;, z_delete = TRUE) { # Store original dimensions original_rows &lt;- nrow(df) original_cols &lt;- ncol(df) # 1. Zero replacement if (any(df == 0)) { # I think cmultRepl already does that print(&quot;Zeros found&quot;) df &lt;- cmultRepl(df, method = zero_method, output = &quot;prop&quot;, z.warning = 0.8, z.delete = z_delete) df &lt;- df * 100 } # Print removed rows and columns removed_rows &lt;- original_rows - nrow(df) removed_cols &lt;- original_cols - ncol(df) cat(&quot;Rows (samples) removed:&quot;, removed_rows, &quot;
&quot;) cat(&quot;Columns (taxa) removed:&quot;, removed_cols, &quot;
&quot;) #plot_abundance_heatmap(df) # Geometric mean function geometric_mean &lt;- function(x) { # Use log to avoid underflow exp(mean(log(x), na.rm = TRUE)) } # 2. Calculate geometric mean of the parts (taxa) of the data set. taxa_geometric_means &lt;- apply(df, 2, geometric_mean) # 3. Center data df_centered &lt;- sweep(df, 2, taxa_geometric_means, FUN = &quot;/&quot;) df_centered &lt;- as.matrix(df_centered) # Compute the Variation Matrix variation_matrix &lt;- outer( 1:ncol(df_centered), 1:ncol(df_centered), Vectorize(function(i, j) var(log(df_centered[, i] / df_centered[, j]), na.rm = TRUE)) ) # Calculate Total Variance D &lt;- ncol(df_centered) # Number of taxa (columns) totvar &lt;- (1 / (2 * D)) * sum(variation_matrix, na.rm = TRUE) # 4. Scale data power_exponent &lt;- 1 / sqrt(totvar) df_scaled &lt;- df_centered^power_exponent # print(df_scaled) # CLR transform data clr_transform &lt;- function(x) { log(x) - mean(log(x), na.rm = TRUE) } df_clr &lt;- t(apply(df_scaled, 1, clr_transform)) df_clr &lt;- as.data.frame(df_clr) df_clr_dist &lt;- t(apply(df, 1, clr_transform)) df_clr_dist &lt;- as.data.frame(df_clr_dist) # Perform PCA on zero replaced, centered, scaled, and CLR transformed df pca_result &lt;- prcomp(df_clr, center = FALSE, scale. = FALSE) pca_result_dist &lt;- prcomp(df_clr_dist, center = TRUE, scale. = TRUE) return(list( df_clr = df_clr, df_clr_dist = df_clr_dist, pca_result=pca_result, pca_result_dist=pca_result_dist)) } 1.3.4 fit_and_analyze_model fit_and_analyze_model &lt;- function(model = c(&quot;lm&quot;, &quot;glm&quot;), distribution = NULL, response_var, explanatory_var, data) { model &lt;- match.arg(model) # Restrict to &quot;lm&quot; or &quot;glm&quot; # Construct the model formula model_formula &lt;- as.formula(paste(response_var, &quot;~&quot;, explanatory_var)) # Initialize all possible return objects anova_result &lt;- NULL md &lt;- NULL simResids &lt;- NULL if (model == &quot;lm&quot;) { # Continuous floats (any real number) md &lt;- lm(model_formula, data = data) anova_result &lt;- broom::tidy(Anova(md, test.statistic = &quot;F&quot;)) } else if (model == &quot;glm&quot;) { # Counts (integers ≥0): poisson, quasipoisson (accounts overdispersion) # Proportions (0–1 continuous): quasibinomial GLM (accounts overdispersion) but beta regression (not GLM) Preferred over quasibinomial GLM # Continuous floats (any real number): gaussian, Gamma (continuous positive data, skewed to the right) if (is.null(distribution)) { stop(&quot;You must specify a distribution family for glm.&quot;) } md &lt;- glm(model_formula, family = distribution, data = data) if (!grepl(&quot;^quasi&quot;, distribution)) { # Use DHARMa only on supported distributions simResids &lt;- simulateResiduals(md) anova_result &lt;- broom::tidy(Anova(md, test.statistic = &quot;F&quot;)) # ANOVA with F test } else { anova_result &lt;- broom::tidy(Anova(md, test.statistic = &quot;Wald&quot;)) # ANOVA with Chi-squared test } } result &lt;- list( model_fit = md, anova = anova_result ) if (!is.null(simResids)) { result$simResidual &lt;- simResids } return(result) } 1.3.5 pivot_phylo pivot_phylo &lt;- function(phyloseq_obj, glom = TRUE, tax_transform = TRUE, taxon_level, tr_method) { if (glom == TRUE &amp;&amp; !is.null(taxon_level)) { phyloseq_obj &lt;- prune_taxa(taxa_sums(phyloseq_obj) &gt; 0, phyloseq_obj) phyloseq_obj &lt;- tax_glom(phyloseq_obj, taxon_level) } else { . } if (tax_transform == TRUE &amp;&amp; !is.null(tr_method)) { phyloseq_obj &lt;- tax_transform(phyloseq_obj, tr_method) } else { . } pivot_dataframe &lt;- data.frame(otu_table(phyloseq_obj)) %&gt;% rownames_to_column(var = &quot;genome&quot;) %&gt;% pivot_longer(-genome, names_to = &quot;microsample&quot;, values_to = &quot;abundance&quot;) %&gt;% filter(abundance &gt; 0) %&gt;% left_join(data.frame(tax_table(phyloseq_obj)) %&gt;% rownames_to_column(var = &quot;genome&quot;), by = &quot;genome&quot;) %&gt;% left_join(data.frame(sample_data(phyloseq_obj)) %&gt;% rownames_to_column(var = &quot;microsample&quot;), by = &quot;microsample&quot;) # Re-order levels taxa_levels &lt;- c(&quot;domain&quot;, &quot;phylum&quot;, &quot;class&quot;, &quot;order&quot;, &quot;family&quot;, &quot;genus&quot;, &quot;species&quot;) # Iterate over taxonomic levels for (taxa in taxa_levels) { # Check if the column has more than one unique value if (taxa %in% colnames(pivot_dataframe) &amp;&amp; length(unique(pivot_dataframe[[taxa]])) &gt; 1) { # Convert each taxonomic level to a factor with levels ordered by abundance pivot_dataframe &lt;- pivot_dataframe %&gt;% mutate( !!taxa := factor( !!sym(taxa), levels = pivot_dataframe %&gt;% group_by(!!sym(taxa)) %&gt;% summarise(total_abundance = sum(abundance, na.rm = TRUE), .groups = &quot;drop&quot;) %&gt;% arrange(desc(total_abundance)) %&gt;% pull(!!sym(taxa)) ) # Extract ordered levels ) } } return(pivot_dataframe) } 1.3.6 spatial_cryosections spatial_cryosections &lt;- function(cryosection_list, metadata_df, comm_clr) { cryosection_dfs &lt;- list() mantel_results &lt;- list() mantelcor_results &lt;- list() decay_dfs &lt;- list() distance_decay_plots &lt;- list() structure_results &lt;- list() for (cryosection in cryosection_list) { # Filter metadata for this section metadata_data &lt;- metadata_df %&gt;% filter(cryosection == !!cryosection, !is.na(.data$Xcoord), !is.na(.data$Ycoord)) # Filter community data comm_data &lt;- comm_clr %&gt;% data.frame() %&gt;% rownames_to_column(var = &quot;microsample&quot;) %&gt;% filter(microsample %in% metadata_data$microsample) %&gt;% column_to_rownames(var = &quot;microsample&quot;) cryosection_dfs[[cryosection]] &lt;- list( comm_clr = comm_data, metadata = metadata_data ) # Mantel correlogram mantel &lt;- vegan::mantel( dist(comm_data), dist(metadata_data[, c(&quot;Xcoord&quot;, &quot;Ycoord&quot;)]), permutations = 999 ) mantel_results[[cryosection]] &lt;- mantel # Mantel correlogram correlog &lt;- vegan::mantel.correlog( D.eco = dist(comm_data), D.geo = dist(metadata_data[, c(&quot;Xcoord&quot;, &quot;Ycoord&quot;)]), nperm = 999 ) mantelcor_results[[cryosection]] &lt;- correlog # Distance decay toplot &lt;- data.frame( spat_dist = as.numeric(dist(metadata_data[, c(&quot;Xcoord&quot;, &quot;Ycoord&quot;)])), comm_dist = as.numeric(dist(comm_data)) ) decay_dfs[[cryosection]] &lt;- toplot # Plot p &lt;- ggplot(toplot, aes(x = spat_dist, y = comm_dist)) + # geom_point() + geom_smooth() + xlab(&quot;Spatial distance (μm)&quot;) + ylab(&quot;Aitchison 
distance&quot;) + custom_ggplot_theme + # ggtitle(paste(&quot;Distance Decay -&quot;, cryosection)) ggtitle(paste(cryosection)) distance_decay_plots[[cryosection]] &lt;- p # Print summary # print(paste(&quot;Summary for&quot;, cryosection)) # print(summary(lm(comm_dist ~ spat_dist, data = toplot))) #### Complex spatial structures # set.seed(111) # spat_SWNs&lt;-listw.candidates(data.frame(metadata_data[,c(&quot;Xcoord&quot;,&quot;Ycoord&quot;)]), # nb = c(&quot;gab&quot;), # weights = c(&quot;fdown&quot;, &quot;fup&quot;), # y_fdown = c(2,5), y_fup = c(0.1,0.5)) # W_sel &lt;- listw.select(comm_data, spat_SWNs, MEM.autocor = &quot;positive&quot;, # p.adjust = T, method=&quot;FWD&quot;) # structure_results[[cryosection]] &lt;- W_sel } return(list( cryosection_dfs = cryosection_dfs, mantel_results = mantel_results, mantelcor_results = mantelcor_results, decay_dfs = decay_dfs, distance_decay_plots = distance_decay_plots, structure_results = structure_results )) } 1.3.7 lawsonibacter_mantel_analysis lawsonibacter_mantel_analysis &lt;- function(data, animal_id, circul_selection) { # 1. Filter and prepare presence-absence matrix if (circul_selection == &quot;Y&quot;) { filtered_data &lt;- data %&gt;% filter( cryosection %in% c(&quot;G121eI103A&quot;, &quot;G103bI301A&quot;), !microsample %in% c(&quot;M300840&quot;, &quot;M301068&quot;, &quot;M301085&quot;, &quot;M301084&quot;), circul == circul_selection, animal == animal_id ) } else { message(&quot;circul_selection is not &#39;Y&#39;; skipping circul filter.&quot;) filtered_data &lt;- data %&gt;% filter( cryosection %in% c(&quot;G121eI103A&quot;, &quot;G103bI301A&quot;), !microsample %in% c(&quot;M300840&quot;, &quot;M301068&quot;, &quot;M301085&quot;, &quot;M301084&quot;), animal == animal_id ) } # Presence Absence # 1. Build presence-absence matrix lawsonibacter_pa &lt;- filtered_data %&gt;% mutate(presence = ifelse(abundance &gt; 0, 1, 0)) %&gt;% select(microsample, genome, presence) %&gt;% pivot_wider(names_from = genome, values_from = presence, values_fill = 0) %&gt;% column_to_rownames(&quot;microsample&quot;) # 2. Community distance comm_dist_pa &lt;- vegan::vegdist(lawsonibacter_pa, method = &quot;jaccard&quot;) # 3. Spatial coordinates coords_pa &lt;- filtered_data %&gt;% distinct(microsample, Xcoord, Ycoord) %&gt;% arrange(microsample) coords_pa &lt;- coords_pa[match(rownames(lawsonibacter_pa), coords_pa$microsample), ] # 4. Spatial distance spatial_dist_pa &lt;- dist(coords_pa[, c(&quot;Xcoord&quot;, &quot;Ycoord&quot;)]) # 5. Mantel test mantel_result_pa &lt;- vegan::mantel(comm_dist_pa, spatial_dist_pa, permutations = 999) # 6. Mantel correlogram mantelcor_result_pa &lt;- vegan::mantel.correlog( D.eco = comm_dist_pa, D.geo = spatial_dist_pa, nperm = 999 ) # CLR # 1. Build count matrix and CLR transformation lawsonibacter_clr &lt;- filtered_data %&gt;% select(microsample, genome, abundance) %&gt;% pivot_wider(names_from = genome, values_from = abundance, values_fill = 0) %&gt;% column_to_rownames(&quot;microsample&quot;) lawsonibacter_clr &lt;- cmultRepl(lawsonibacter_clr, method = &quot;GBM&quot;, output = &quot;prop&quot;, z.warning = 0.95) clr_transform &lt;- function(x) { log(x) - mean(log(x), na.rm = TRUE) } lawsonibacter_clr &lt;- data.frame(t(apply(lawsonibacter_clr, 1, clr_transform))) # 2. Community distance comm_dist_clr &lt;- vegan::vegdist(lawsonibacter_clr, method = &quot;euclidean&quot;) # 2. Spatial coordinates coords_clr &lt;- filtered_data %&gt;% distinct(microsample, Xcoord, Ycoord) %&gt;% arrange(microsample) %&gt;% filter(microsample %in% c(rownames(lawsonibacter_clr))) coords_clr &lt;- coords_clr[match(rownames(lawsonibacter_clr), coords_clr$microsample), ] # 4. Spatial distance spatial_dist_clr &lt;- dist(coords_clr[, c(&quot;Xcoord&quot;, &quot;Ycoord&quot;)]) # 5. Mantel test mantel_result_clr &lt;- vegan::mantel(comm_dist_clr, spatial_dist_clr, permutations = 999) # 6. Mantel correlogram mantelcor_result_clr &lt;- vegan::mantel.correlog( D.eco = comm_dist_clr, D.geo = spatial_dist_clr, nperm = 999 ) distance_clr_df &lt;- data.frame( spat_dist = as.numeric(spatial_dist_clr), comm_dist = as.numeric(comm_dist_clr) ) clr_lm &lt;- aovperm(lmperm(comm_dist ~ spat_dist, data = distance_clr_df, np=10000)) return(list( animal = animal_id, mantel_pa = mantel_result_pa, correlogram_pa = mantelcor_result_pa, mantel_clr = mantel_result_clr, correlogram_clr = mantelcor_result_clr, clr_lm = clr_lm )) } University of Copenhagen, carlotta.pietroni@sund.ku.dk↩︎ University of Copenhagen, antton.alberdi@sund.ku.dk↩︎ University of Copenhagen, amalia.bogri@sund.ku.dk↩︎
